(()=>{const video=document.getElementById('video'),notice=document.getElementById('notice');let model,stream,timer,loading=false,version=0;const say=(text,error=false)=>{notice.textContent=text;notice.classList.toggle('error',error)};
function openPalm(points){if(!points||points.length!==21)return false;const d=(a,b)=>Math.hypot(points[a].x-points[b].x,points[a].y-points[b].y);const width=Math.max(d(5,17),.02);return [[8,6,5],[12,10,9],[16,14,13],[20,18,17]].every(([tip,pip,base])=>d(tip,0)>d(pip,0)*1.07&&d(tip,base)>width*.45)&&d(8,12)<width*.8&&d(12,16)<width*.8&&d(16,20)<width*.8}
function stop(){version++;clearTimeout(timer);stream?.getTracks().forEach(t=>t.stop());stream=null;video.srcObject=null;document.body.classList.remove('camera-on');loading=false;room.running=false}
async function start(){loading=true;const id=++version;say('Starting camera…',true);try{const capture=await navigator.mediaDevices.getUserMedia({video:{width:{ideal:320},height:{ideal:240},frameRate:{ideal:10,max:15},facingMode:'user'},audio:false});if(id!==version){capture.getTracks().forEach(t=>t.stop());return}stream=capture;video.srcObject=stream;await video.play();document.body.classList.add('camera-on');say('Loading palm detection…',true);const vision=await import('https://cdn.jsdelivr.net/npm/@mediapipe/tasks-vision@0.10.21/vision_bundle.mjs');const files=await vision.FilesetResolver.forVisionTasks('https://cdn.jsdelivr.net/npm/@mediapipe/tasks-vision@0.10.21/wasm');if(id!==version)return;if(!model)model=await vision.HandLandmarker.createFromOptions(files,{baseOptions:{modelAssetPath:'https://storage.googleapis.com/mediapipe-models/hand_landmarker/hand_landmarker/float16/1/hand_landmarker.task'},runningMode:'IMAGE',numHands:1,minHandDetectionConfidence:.45,minHandPresenceConfidence:.45});if(id!==version)return;loading=false;say('');function sample(){if(id!==version)return;try{if(video.readyState>=2){const result=model.detect(video);room.running=openPalm(result.landmarks?.[0])}}catch{room.running=false;say('Palm detection failed. Press 1 twice to retry.',true)}timer=setTimeout(sample,1000)}sample()}catch(e){if(id!==version)return;stop();say(e.name==='NotAllowedError'?'Camera blocked. Allow camera access in browser settings, then press 1.':'Camera could not start. Check your connection and press 1 to retry.',true)}}
window.toggleCamera=()=>{if(stream||loading){stop();say('')}else start()};addEventListener('pagehide',stop)})();
